with open(OUT, "w") as f:
    for i, rec in enumerate(sel):
        m = {x["role"]: x["content"] for x in rec["messages"]}
        head, body = STANCES[i]
        ca = "Analytical stance under test: " + head + "\n\n" + frame + "\n\n" + body + "\n\n" + critique
        row = {
            "source_id": rec["id"],
            "teacher_lane": "teacher-B",
            "teacher_model": "claude-opus-5-current",
            "calibration_status": "provisional",
            "decision": "rewrite",
            "source_user": m["user"],
            "source_assistant": m["assistant"],
            "corrected_answer": ca,
            "quality_dimensions": {"technical_correctness": 3, "instruction_coverage": 2, "operational_safety": 2},
            "risks": RISKS + [EXTRA_RISK[i]],
            "evidence_required": EVIDENCE + [EXTRA_EVIDENCE[i]],
            "confidence": CONF[i],
        }
        f.write(json.dumps(row, ensure_ascii=False) + "\n")
